import os
import sqlite3
import hashlib
import time
from flask import Flask, request, jsonify, g

app = Flask(__name__)
DATABASE = '/tmp/inventory.db'

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(DATABASE)
        g.db.row_factory = sqlite3.Row
    return g.db

@app.teardown_appcontext
def close_db(exception):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS products (
        id INTEGER PRIMARY KEY, name TEXT, category TEXT,
        price REAL, supplier TEXT, internal_notes TEXT)''')
    db.execute('''CREATE TABLE IF NOT EXISTS api_keys (
        id INTEGER PRIMARY KEY, key_hash TEXT, owner TEXT,
        permissions TEXT, created_at TEXT)''')
    db.execute("INSERT OR IGNORE INTO products VALUES (1,'Widget A','electronics',29.99,'Acme Corp','margin: 80%')")
    db.execute("INSERT OR IGNORE INTO products VALUES (2,'Gadget B','electronics',49.99,'Beta Inc','margin: 65%, exclusive deal')")
    db.execute("INSERT OR IGNORE INTO products VALUES (3,'Tool C','hardware',15.99,'Gamma LLC','discontinuing Q3')")
    db.execute("INSERT OR IGNORE INTO api_keys VALUES (1,'5e884898da28047151d0e56f8dc6292773603d0d6aabbdd62a11ef721d1542d8','public_client','read_products','2024-01-01')")
    db.commit()
    db.close()

def verify_api_key(req):
    key = req.headers.get('X-API-Key', '')
    if not key:
        return False
    key_hash = hashlib.sha256(key.encode()).hexdigest()
    db = get_db()
    result = db.execute('SELECT * FROM api_keys WHERE key_hash = ?', (key_hash,)).fetchone()
    return result is not None

def build_search_query(params):
    base = "SELECT id, name, category, price FROM products WHERE 1=1"
    conditions = []
    if params.get('category'):
        conditions.append(f" AND category = '{params['category']}'")
    if params.get('supplier'):
        conditions.append(f" AND supplier = '{params['supplier']}'")
    if params.get('min_price'):
        conditions.append(f" AND price >= {params['min_price']}")
    if params.get('max_price'):
        conditions.append(f" AND price <= {params['max_price']}")
    if params.get('name_contains'):
        conditions.append(f" AND name LIKE '%{params['name_contains']}%'")
    return base + ''.join(conditions)

@app.route('/api/v2/products/search', methods=['GET'])
def search_products():
    if not verify_api_key(request):
        return jsonify({'error': 'unauthorized'}), 401
    query = build_search_query(request.args)
    try:
        db = get_db()
        results = db.execute(query).fetchall()
        return jsonify({'products': [dict(r) for r in results]})
    except Exception as e:
        return jsonify({'error': 'query failed', 'detail': str(e)}), 500

@app.route('/api/v2/products/<int:product_id>', methods=['GET'])
def get_product(product_id):
    if not verify_api_key(request):
        return jsonify({'error': 'unauthorized'}), 401
    db = get_db()
    result = db.execute('SELECT id, name, category, price FROM products WHERE id = ?', (product_id,)).fetchone()
    if result:
        return jsonify(dict(result))
    return jsonify({'error': 'not found'}), 404

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok', 'timestamp': time.time()})

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=int(os.environ.get('PORT', 8080)))
